// Regenerates the localisation code and registers every language that has a
// lib/l10n/app_<locale>.arb file with iOS and Android.
//
// Usage: dart run tool/l10n.dart
//
// Run it after adding, removing or editing an ARB file. CI runs it and fails
// if anything changes, so the generated files never drift.
import 'dart:io';

const _arbDir = 'lib/l10n';
const _plist = 'ios/Runner/Info.plist';
const _manifest = 'android/app/src/main/AndroidManifest.xml';
const _localesConfig = 'android/app/src/main/res/xml/locales_config.xml';

Future<void> main() async {
  // gen-l10n doesn't delete the code of a removed language.
  for (final file in Directory(_arbDir).listSync().whereType<File>()) {
    final locale = RegExp(r'app_localizations_(\w+)\.dart$').firstMatch(file.path)?.group(1);
    if (locale != null && !File('$_arbDir/app_$locale.arb').existsSync()) {
      file.deleteSync();
      stdout.writeln('Deleted ${file.path}');
    }
  }

  final gen = await Process.run('flutter', ['gen-l10n'], runInShell: true);
  stdout.write(gen.stdout);
  stderr.write(gen.stderr);
  if (gen.exitCode != 0) exit(gen.exitCode);

  final locales = _locales();
  _writeIfChanged(_plist, _withPlistLocales(File(_plist).readAsStringSync(), locales));
  _writeIfChanged(_localesConfig, _androidLocalesConfig(locales));
  _writeIfChanged(_manifest, _withLocaleConfigAttribute(File(_manifest).readAsStringSync()));
  stdout.writeln('Languages: ${locales.join(', ')}');
}

/// BCP 47 tags from the ARB file names, English (the template) first:
/// app_pt_BR.arb becomes pt-BR.
List<String> _locales() {
  final tags =
      Directory(_arbDir)
          .listSync()
          .map((f) => f.uri.pathSegments.last)
          .map((name) => RegExp(r'^app_(.+)\.arb$').firstMatch(name)?.group(1))
          .whereType<String>()
          .map((locale) => locale.replaceAll('_', '-'))
          .toList()
        ..sort();
  tags.remove('en');
  return ['en', ...tags];
}

String _withPlistLocales(String plist, List<String> locales) {
  final array = [
    '\t<key>CFBundleLocalizations</key>',
    '\t<array>',
    for (final l in locales) '\t\t<string>$l</string>',
    '\t</array>',
  ].join('\n');
  final existing = RegExp(r'\t<key>CFBundleLocalizations</key>\n\t<array>[\s\S]*?</array>');
  if (existing.hasMatch(plist)) return plist.replaceFirst(existing, array);
  // Insert after the development region entry.
  final anchor = RegExp(r'\t<key>CFBundleDevelopmentRegion</key>\n\t<string>[^<]*</string>');
  final match = anchor.firstMatch(plist) ?? (throw StateError('CFBundleDevelopmentRegion not found in $_plist'));
  return plist.replaceRange(match.end, match.end, '\n$array');
}

String _androidLocalesConfig(List<String> locales) => [
  '<?xml version="1.0" encoding="utf-8"?>',
  '<!-- Generated by tool/l10n.dart from lib/l10n/app_*.arb. Do not edit. -->',
  '<locale-config xmlns:android="http://schemas.android.com/apk/res/android">',
  for (final l in locales) '    <locale android:name="$l"/>',
  '</locale-config>',
  '',
].join('\n');

/// Points the app at locales_config.xml so Android 13+ offers a per-app
/// language setting.
String _withLocaleConfigAttribute(String manifest) {
  if (manifest.contains('android:localeConfig=')) return manifest;
  return manifest.replaceFirstMapped(
    RegExp(r'\n(\s*)android:label='),
    (m) => '\n${m[1]}android:localeConfig="@xml/locales_config"${m[0]}',
  );
}

void _writeIfChanged(String path, String contents) {
  final file = File(path);
  if (file.existsSync() && file.readAsStringSync() == contents) return;
  file
    ..createSync(recursive: true)
    ..writeAsStringSync(contents);
  stdout.writeln('Updated $path');
}
